// Local, dependency-free point-cloud reader and interactive canvas preview.
const POINT_TYPES={char:['getInt8',1],int8:['getInt8',1],uchar:['getUint8',1],uint8:['getUint8',1],short:['getInt16',2],int16:['getInt16',2],ushort:['getUint16',2],uint16:['getUint16',2],int:['getInt32',4],int32:['getInt32',4],uint:['getUint32',4],uint32:['getUint32',4],float:['getFloat32',4],float32:['getFloat32',4],double:['getFloat64',8],float64:['getFloat64',8]};
const pointPreviewPromises=new Map();

function parsePointPreview(buffer){
 const view=new DataView(buffer),magic=String.fromCharCode(...new Uint8Array(buffer,0,4));
 if(buffer.byteLength<36||!['PCV1','PCV2'].includes(magic))throw Error('data');
 const total=view.getUint32(4,true),count=view.getUint32(8,true),stride=magic==='PCV2'?14:13;
 if(!count||buffer.byteLength<36+count*stride)throw Error('data');
 const min=[view.getFloat32(12,true),view.getFloat32(16,true),view.getFloat32(20,true)],max=[view.getFloat32(24,true),view.getFloat32(28,true),view.getFloat32(32,true)];
 const positions=new Float32Array(count*3),strengths=new Uint8Array(count),constants=new Uint8Array(count);
 for(let i=0;i<count;i++){const base=36+i*stride,key=i*3;positions[key]=view.getFloat32(base,true);positions[key+1]=view.getFloat32(base+4,true);positions[key+2]=view.getFloat32(base+8,true);strengths[i]=view.getUint8(base+12);constants[i]=stride===14?view.getUint8(base+13):strengths[i]}
 return {positions,strengths,constants,count,total,min,max};
}

const BUNDLED_PREVIEW_BASE64='';
let bundledPreviewCloud=null;
function loadBundledPointCloudPreview(path,version){
 if(!bundledPreviewCloud){
  const encoded=atob(BUNDLED_PREVIEW_BASE64),bytes=new Uint8Array(encoded.length);
  for(let i=0;i<encoded.length;i++)bytes[i]=encoded.charCodeAt(i);
  bundledPreviewCloud=parsePointPreview(bytes.buffer);
 }
 return Promise.resolve(bundledPreviewCloud);
}

function pointHeader(bytes){
 const limit=Math.min(bytes.length,1024*1024),needle=[101,110,100,95,104,101,97,100,101,114];
 for(let i=0;i<limit-needle.length;i++){
  if(bytes[i]!==needle[0])continue;
  let match=true;for(let j=1;j<needle.length;j++)if(bytes[i+j]!==needle[j]){match=false;break}
  if(match){let end=i+needle.length;while(end<bytes.length&&bytes[end]!==10)end++;if(end>=bytes.length)throw Error('header');return {text:new TextDecoder('ascii').decode(bytes.subarray(0,end+1)),offset:end+1}}
 }
 throw Error('header');
}

async function parsePointCloudFile(file,maxPoints=40000,onProgress=()=>{}){
 const name=(file.name||'').toLowerCase(),limit=Math.max(1000,maxPoints);
 if(name.endsWith('.ply')&&typeof file.slice==='function'){
  const prefix=new Uint8Array(await file.slice(0,Math.min(file.size,1024*1024)).arrayBuffer()),header=pointHeader(prefix);
  if(header.text.includes('format binary_little_endian')||header.text.includes('format binary_big_endian'))return parsePlySlices(file,header,limit,onProgress);
 }
 const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);
 if(name.endsWith('.ply')||new TextDecoder('ascii').decode(bytes.subarray(0,4)).startsWith('ply'))return parsePlyPoints(buffer,limit);
 if(/\.(xyz|pts|txt|csv)$/i.test(name))return parseTextPoints(buffer,limit);
 throw Error('format');
}

async function parsePlySlices(file,header,maxPoints,onProgress){
 const lines=header.text.replace(/\r/g,'').split('\n');let format='',count=0,element='',firstElement='',properties=[];
 for(const raw of lines){const parts=raw.trim().split(/\s+/);if(parts[0]==='format')format=parts[1];if(parts[0]==='element'){element=parts[1];if(!firstElement)firstElement=element;if(element==='vertex')count=Number(parts[2])}if(parts[0]==='property'&&element==='vertex'){if(parts[1]==='list')throw Error('format');properties.push({type:parts[1],name:parts[2]})}}
 if(firstElement!=='vertex'||!count||!properties.some(p=>p.name==='x')||!properties.some(p=>p.name==='y')||!properties.some(p=>p.name==='z'))throw Error('format');
 const little=format==='binary_little_endian';if(!little&&format!=='binary_big_endian')throw Error('format');
 const stride=properties.reduce((sum,p)=>{if(!POINT_TYPES[p.type])throw Error('format');return sum+POINT_TYPES[p.type][1]},0);
 if(header.offset+count*stride>file.size)throw Error('data');
 const fields={};let fieldOffset=0;for(const property of properties){fields[property.name]={offset:fieldOffset,type:property.type};fieldOffset+=POINT_TYPES[property.type][1]}
 const windows=count<=maxPoints?1:Math.min(24,Math.max(1,Math.ceil(maxPoints/3000))),verticesPerWindow=Math.min(count,Math.ceil(maxPoints/windows)),positions=new Float32Array(Math.min(count,maxPoints)*3),strengths=new Uint8Array(Math.min(count,maxPoints));
 let used=0,min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];
 const accept=(x,y,z,intensity)=>{if(![x,y,z].every(Number.isFinite)||used>=strengths.length)return;const k=used*3;positions[k]=x;positions[k+1]=y;positions[k+2]=z;strengths[used]=Number.isFinite(intensity)?Math.max(0,Math.min(255,Math.round(38+Math.log1p(Math.max(0,intensity))*27))):160;for(let j=0;j<3;j++){const value=positions[k+j];min[j]=Math.min(min[j],value);max[j]=Math.max(max[j],value)}used++};
 for(let windowIndex=0;windowIndex<windows;windowIndex++){
  const startVertex=windows===1?0:Math.floor((count-verticesPerWindow)*windowIndex/(windows-1));
  const start=header.offset+startVertex*stride,end=start+verticesPerWindow*stride,chunk=await file.slice(start,end).arrayBuffer(),view=new DataView(chunk);
  const read=(base,name)=>{const field=fields[name];if(!field)return NaN;const [method,size]=POINT_TYPES[field.type];return size===1?view[method](base+field.offset):view[method](base+field.offset,little)};
  for(let i=0;i<verticesPerWindow&&used<strengths.length;i++){const base=i*stride;accept(read(base,'x'),read(base,'y'),read(base,'z'),read(base,fields.scalar_strength?'scalar_strength':'intensity'))}
  onProgress((windowIndex+1)/windows);
 }
 if(!used)throw Error('data');
 return {positions:positions.subarray(0,used*3),strengths:strengths.subarray(0,used),count:used,total:count,min,max};
}

function parsePlyPoints(buffer,maxPoints){
 const bytes=new Uint8Array(buffer),header=pointHeader(bytes),lines=header.text.replace(/\r/g,'').split('\n');
 let format='',count=0,element='',firstElement='',properties=[];
 for(const raw of lines){const parts=raw.trim().split(/\s+/);if(parts[0]==='format')format=parts[1];if(parts[0]==='element'){element=parts[1];if(!firstElement)firstElement=element;if(element==='vertex')count=Number(parts[2])}if(parts[0]==='property'&&element==='vertex'){if(parts[1]==='list')throw Error('format');properties.push({type:parts[1],name:parts[2]})}}
 if(firstElement!=='vertex'||!count||!properties.some(p=>p.name==='x')||!properties.some(p=>p.name==='y')||!properties.some(p=>p.name==='z'))throw Error('format');
 const positions=new Float32Array(Math.min(maxPoints,count)*3),strengths=new Uint8Array(Math.min(maxPoints,count));
 const step=Math.max(1,Math.ceil(count/maxPoints));let used=0,min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];
 const accept=(x,y,z,intensity)=>{if(![x,y,z].every(Number.isFinite)||used*3+2>=positions.length)return;const k=used*3;positions[k]=x;positions[k+1]=y;positions[k+2]=z;strengths[used]=Number.isFinite(intensity)?Math.max(0,Math.min(255,Math.round(38+Math.log1p(Math.max(0,intensity))*27))):160;for(let j=0;j<3;j++){const value=positions[k+j];min[j]=Math.min(min[j],value);max[j]=Math.max(max[j],value)}used++};
 if(format==='ascii'){
  const body=new TextDecoder('utf-8').decode(bytes.subarray(header.offset));let cursor=0;
  for(let i=0;i<count&&cursor<body.length;i++){let next=body.indexOf('\n',cursor);if(next<0)next=body.length;if(i%step===0){const parts=body.slice(cursor,next).trim().split(/\s+/),row={};properties.forEach((p,j)=>{row[p.name]=Number(parts[j])});accept(row.x,row.y,row.z,row.scalar_strength??row.intensity)}cursor=next+1}
 }else if(format==='binary_little_endian'||format==='binary_big_endian'){
  const little=format==='binary_little_endian',view=new DataView(buffer),stride=properties.reduce((sum,p)=>{if(!POINT_TYPES[p.type])throw Error('format');return sum+POINT_TYPES[p.type][1]},0);
  if(header.offset+count*stride>buffer.byteLength)throw Error('data');
  const fields={};let offset=0;for(const property of properties){fields[property.name]={offset,type:property.type};offset+=POINT_TYPES[property.type][1]}
  const read=(base,name)=>{const field=fields[name];if(!field)return NaN;const [method,size]=POINT_TYPES[field.type];return size===1?view[method](base+field.offset):view[method](base+field.offset,little)};
  for(let i=0;i<count;i+=step){const base=header.offset+i*stride;accept(read(base,'x'),read(base,'y'),read(base,'z'),read(base,fields.scalar_strength?'scalar_strength':'intensity'))}
 }else throw Error('format');
 if(!used)throw Error('data');
 return {positions:positions.subarray(0,used*3),strengths:strengths.subarray(0,used),count:used,total:count,min,max};
}

function parseTextPoints(buffer,maxPoints){
 const text=new TextDecoder('utf-8').decode(buffer),lines=text.split(/\r?\n/),step=Math.max(1,Math.ceil(lines.length/maxPoints)),positions=new Float32Array(Math.min(maxPoints,lines.length)*3),strengths=new Uint8Array(Math.min(maxPoints,lines.length));
 let used=0,min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];
 for(let i=0;i<lines.length;i+=step){const row=lines[i].trim();if(!row||row.startsWith('#'))continue;const parts=row.split(/[\s,;]+/).map(Number);if(parts.length<3||!parts.slice(0,3).every(Number.isFinite))continue;const k=used*3;if(k+2>=positions.length)break;for(let j=0;j<3;j++){positions[k+j]=parts[j];min[j]=Math.min(min[j],parts[j]);max[j]=Math.max(max[j],parts[j])}strengths[used]=160;used++}
 if(!used)throw Error('data');return {positions:positions.subarray(0,used*3),strengths:strengths.subarray(0,used),count:used,total:lines.length,min,max};
}

function mountPointCloud(canvas,cloud,view,geometryValues){
 const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)return {destroy(){}};
 const state=view||{yaw:1.3,pitch:.15,zoom:1,panX:0,panY:0,geometry:false,colorMode:'plain'},center=cloud.min.map((v,i)=>(v+cloud.max[i])/2),palette=Array.from({length:16},(_,i)=>{const n=Math.round(68+i*11);return `rgb(${n},${n},${Math.min(255,n+5)})`});
 let width=0,height=0,raf=0,observer=null,drag=null,closed=false;
 const project=(x,y,z,cy,sy,cp,sp)=>{const rx=cy*x-sy*y,ry=sy*x+cy*y;return [rx,cp*z-sp*ry]};
 function draw(){
  raf=0;if(closed)return;
  const rect=canvas.getBoundingClientRect(),w=Math.max(1,Math.round(rect.width)),h=Math.max(1,Math.round(rect.height)),ratio=Math.min(2,window.devicePixelRatio||1);
  if(w!==width||h!==height){width=w;height=h;canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio)}
  ctx.setTransform(ratio,0,0,ratio,0,0);
  const background=ctx.createLinearGradient(0,0,0,h);background.addColorStop(0,'#0c5277');background.addColorStop(1,'#020609');ctx.fillStyle=background;ctx.fillRect(0,0,w,h);
  const cy=Math.cos(state.yaw),sy=Math.sin(state.yaw),cp=Math.cos(state.pitch),sp=Math.sin(state.pitch),points=cloud.positions,intensities=cloud.strengths;
  let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;
  for(let i=0;i<points.length;i+=3){const [px,py]=project(points[i]-center[0],points[i+1]-center[1],points[i+2]-center[2],cy,sy,cp,sp);minX=Math.min(minX,px);maxX=Math.max(maxX,px);minY=Math.min(minY,py);maxY=Math.max(maxY,py)}
  const base=Math.min(w*.82/Math.max(1,maxX-minX),h*.82/Math.max(1,maxY-minY)),scale=base*state.zoom,projectedCenterX=(minX+maxX)/2,projectedCenterY=(minY+maxY)/2;
  const toScreen=(x,y,z)=>{const [px,py]=project(x-center[0],y-center[1],z-center[2],cy,sy,cp,sp);return [w/2+(px-projectedCenterX)*scale+state.panX,h/2-(py-projectedCenterY)*scale+state.panY]};
  for(let i=0;i<points.length;i+=3){const [sx,sy2]=toScreen(points[i],points[i+1],points[i+2]);if(sx<-2||sy2<-2||sx>w+2||sy2>h+2)continue;ctx.fillStyle=state.colorMode==='constant'?`hsl(${Math.round(240-(cloud.constants?.[i/3]??128)*240/255)},100%,55%)`:state.colorMode==='strength'?`hsl(${Math.round(240-intensities[i/3]*240/255)},100%,55%)`:'#c8cdd0';ctx.fillRect(sx,sy2,Math.max(1,ratio),Math.max(1,ratio))}
  if(state.geometry){
   const [minCloudX,minCloudY,minCloudZ]=cloud.min,[maxCloudX,maxCloudY,maxCloudZ]=cloud.max;
   const marks=[
    {from:[minCloudX,minCloudY,minCloudZ],to:[maxCloudX,minCloudY,minCloudZ],color:'#5ce483',label:geometryValues?.[0]},
    {from:[maxCloudX,minCloudY,minCloudZ],to:[maxCloudX,maxCloudY,minCloudZ],color:'#f46464',label:geometryValues?.[1]},
    {from:[maxCloudX,maxCloudY,minCloudZ],to:[maxCloudX,maxCloudY,maxCloudZ],color:'#68aaff',label:geometryValues?.[2]}
   ];
   ctx.save();ctx.font='bold 15px Arial';ctx.textBaseline='bottom';
   for(const mark of marks){
    const [x1,y1]=toScreen(...mark.from),[x2,y2]=toScreen(...mark.to),mx=(x1+x2)/2,my=(y1+y2)/2;
    const label=String(mark.label??'');if(label){const textWidth=ctx.measureText(label).width,pad=4;ctx.fillStyle='rgba(2,12,18,.82)';ctx.fillRect(mx-textWidth/2-pad,my-22,textWidth+pad*2,20);ctx.fillStyle=mark.color;ctx.fillText(label,mx-textWidth/2,my-5)}
   }
   ctx.restore();
  }
 }
 const schedule=()=>{if(!raf)raf=requestAnimationFrame(draw)};
 const onDown=e=>{if(e.button!==0&&e.button!==2)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,mode:e.button===2||e.shiftKey?'pan':'rotate'}};
 const onMove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(drag.mode==='pan'){state.panX+=dx;state.panY+=dy}else{state.yaw+=dx*.007;state.pitch=Math.max(-1.5,Math.min(1.5,state.pitch+dy*.007))}schedule()};
 const onUp=()=>{drag=null};
 const onWheel=e=>{e.preventDefault();if(e.shiftKey){state.panY-=e.deltaY*.5;state.panX-=e.deltaX*.5}else state.zoom=Math.max(.08,Math.min(25,state.zoom*Math.exp(-e.deltaY*.0015)));schedule()};
 const onContext=e=>e.preventDefault();canvas.addEventListener('pointerdown',onDown);canvas.addEventListener('pointermove',onMove);canvas.addEventListener('pointerup',onUp);canvas.addEventListener('pointercancel',onUp);canvas.addEventListener('wheel',onWheel,{passive:false});canvas.addEventListener('contextmenu',onContext);
 if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(schedule);observer.observe(canvas)}schedule();
 return {redraw:schedule,destroy(){closed=true;if(raf)cancelAnimationFrame(raf);observer?.disconnect();canvas.removeEventListener('pointerdown',onDown);canvas.removeEventListener('pointermove',onMove);canvas.removeEventListener('pointerup',onUp);canvas.removeEventListener('pointercancel',onUp);canvas.removeEventListener('wheel',onWheel);canvas.removeEventListener('contextmenu',onContext)}};
}
